+import { renderHook } from '@testing-library/react-hooks';
+
+import { useShouldMoveOut } from './useShouldMoveOut';
+
+describe('useShouldMoveOut', () => {
+    it('waits for elements before evaluating the active ID', () => {
+        const onBack = jest.fn();
+        const { rerender } = renderHook(
+            ({ elementID, elementIDs, loadingElements }) =>
+                useShouldMoveOut({ elementID, elementIDs, loadingElements, onBack }),
+            { initialProps: { elementID: 'missing', elementIDs: ['present'], loadingElements: true } }
+        );
+
+        expect(onBack).not.toHaveBeenCalled();
+        rerender({ elementID: 'missing', elementIDs: ['present'], loadingElements: false });
+        expect(onBack).toHaveBeenCalledTimes(1);
+    });
+
+    it.each([
+        [undefined, ['present']],
+        ['', ['present']],
+        ['present', []],
+        ['missing', ['present']],
+    ])('moves back for invalid ID %s in %s', (elementID, elementIDs) => {
+        const onBack = jest.fn();
+        renderHook(() => useShouldMoveOut({ elementID, elementIDs, loadingElements: false, onBack }));
+        expect(onBack).toHaveBeenCalledTimes(1);
+    });
+
+    it('keeps the view open when the active ID is in the list', () => {
+        const onBack = jest.fn();
+        renderHook(() =>
+            useShouldMoveOut({ elementID: 'present', elementIDs: ['other', 'present'], loadingElements: false, onBack })
+        );
+        expect(onBack).not.toHaveBeenCalled();
+    });
+});
